def findItinerary(tickets):
    graph = {}
    for a, b in tickets:
        graph.setdefault(a, []).append(b)
    for a in graph:
        graph[a].sort(reverse=True)
    route = []
    stack = [0]
    while stack:
        u = stack[-1]
        out = graph.get(u)
        if out:
            stack.append(out.pop())
        else:
            route.append(stack.pop())
    route.reverse()
    return route
